steps.output:
Loaded 2 demo pairs

Demo 1:
Input shape: 17x22
Output shape: 17x22
Input non-background: {2, 5}
Output non-background: {8, 2, 5}

Demo 2:
Input shape: 22x22
Output shape: 22x22
Input non-background: {2, 4}
Output non-background: {8, 2, 4}

import json
from copy import deepcopy

def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 1

    # Find wall
    wall_row = -1
    wall_col = -1
    wall_type = None

    for r in range(h):
        if all(grid[r][c] == 2 for c in range(w)):
            wall_row = r
            wall_type = "h"
            break

    if wall_type is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                wall_col = c
                wall_type = "v"
                break

    if wall_type is None:
        return deepcopy(grid)

    # Counts
    counts = {}
    for r in range(h):
        for c in range(w):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1

    bg = max(counts.keys(), key=lambda x: counts[x])

    # Shape
    shape_color = None
    max_count = 0
    for c_val in sorted(counts.keys()):
        if c_val != 2 and c_val != bg and counts[c_val] > max_count:
            max_count = counts[c_val]
            shape_color = c_val

    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == shape_color]
    if not cells:
        return deepcopy(grid)

    # Calculate shift
    if wall_type == "h":
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)

        if wall_row < min_r:
            gap = min_r - wall_row
            direction = -1  # UP
        else:
            gap = wall_row - max_r
            direction = 1  # DOWN

        shift = max(gap - 1, 0)
        offset = -shift if direction == -1 else shift
        new_min_r = min_r + offset
        new_max_r = max_r + offset
    else:
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)

        if wall_col < min_c:
            gap = min_c - wall_col
            direction = -1  # LEFT
        else:
            gap = wall_col - max_c
            direction = 1  # RIGHT

        shift = max(gap - 1, 0)
        offset = -shift if direction == -1 else shift
        new_min_c = min_c + offset
        new_max_c = max_c + offset

    # Output with shape moved
    out = deepcopy(grid)
    for r, c in cells:
        out[r][c] = bg

    for r, c in cells:
        if wall_type == "h":
            nr = r + (new_min_r - min_r)
            out[nr][c] = shape_color
        else:
            nc = c + (new_min_c - min_c)
            out[r][nc] = shape_color

    # Draw 8s: on shape side
    if wall_type == "h":
        if wall_row < min_r:
            line_row = new_max_r + 1
        else:
            line_row = new_min_r - 1
    else:
        if wall_col < min_c:
            line_col = new_max_c + 1
        else:
            line_col = new_min_c - 1

    if wall_type == "h":
        for c in range(w):
            if 0 <= line_row < h:
                out[line_row][c] = 8
    else:
        for r in range(h):
            if 0 <= line_col < w:
                out[r][line_col] = 8

    return out

def main():
    import sys
    input_path = sys.argv[1] if len(sys.argv) > 1 else None
    output_path = sys.argv[2] if len(sys.argv) > 2 else None

    with open(input_path, "r") as f:
        data = json.load(f)

    grid = data["input"]
    result = transform(grid)

    output_data = {
        "input": grid,
        "output": result
    }

    with open(output_path, "w") as f:
        json.dump(output_data, f, indent=2)

    return output_data

if __name__ == "__main__":
    result = main()
